static ssize_t batadv_store_isolation_mark ( struct kobject * kobj , struct attribute * attr , char * buff , size_t count ) { struct net_device * net_dev = batadv_kobj_to_netdev ( kobj ) ; struct batadv_priv * bat_priv = netdev_priv ( net_dev ) ; u32 mark , mask ; char * mask_ptr ; mask = 0xFFFFFFFF ; mask_ptr = strchr ( buff , '/' ) ; if ( mask_ptr ) { * mask_ptr = '\0' ; mask_ptr ++ ; if ( kstrtou32 ( mask_ptr , 16 , & mask ) < 0 ) { return - EINVAL ; } } bat_priv -> isolation_mark_mask = mask ; bat_priv -> isolation_mark = mark & bat_priv -> isolation_mark_mask ; batadv_info ( net_dev , "New skb mark for extended isolation: %#.8x/%#.8x\n" , bat_priv -> isolation_mark , bat_priv -> isolation_mark_mask ) ; return count ; } 